  1→import type { RecordId, Surreal } from "surrealdb";
  2→import type {
  3→  PolicyRecord,
  4→  PolicyRule,
  5→  PolicyGateResult,
  6→  PolicyTraceEntry,
  7→  PolicyGateWarning,
  8→  PolicyEvidenceRequirements,
  9→  IntentEvaluationContext,
 10→} from "./types";
 11→import { evaluateCondition } from "./predicate-evaluator";
 12→import { loadActivePolicies } from "./policy-queries";
 13→
 14→// ---------------------------------------------------------------------------
 15→// Pipeline Types
 16→// ---------------------------------------------------------------------------
 17→
 18→type AnnotatedRule = {
 19→  policyId: string;
 20→  policyVersion: number;
 21→  humanVetoRequired: boolean;
 22→  rule: PolicyRule;
 23→};
 24→
 25→type EvaluatedRule = AnnotatedRule & {
 26→  matched: boolean;
 27→  warnings: PolicyGateWarning[];
 28→};
 29→
 30→type EvaluationResult = {
 31→  evaluatedRules: EvaluatedRule[];
 32→  denyMatched: boolean;
 33→  warnings: PolicyGateWarning[];
 34→};
 35→
 36→// ---------------------------------------------------------------------------
 37→// Pure Pipeline Functions
 38→// ---------------------------------------------------------------------------
 39→
 40→export const deduplicatePolicies = (
 41→  policies: PolicyRecord[],
 42→): PolicyRecord[] => {
 43→  const seen = new Set<string>();
 44→  const result: PolicyRecord[] = [];
 45→
 46→  for (const policy of policies) {
 47→    const id = policy.id.id as string;
 48→    if (!seen.has(id)) {
 49→      seen.add(id);
 50→      result.push(policy);
 51→    }
 52→  }
 53→
 54→  return result;
 55→};
 56→
 57→export const collectAndSortRules = (
 58→  policies: PolicyRecord[],
 59→): AnnotatedRule[] => {
 60→  const annotated = policies.flatMap((policy) =>
 61→    policy.rules.map((rule) => ({
 62→      policyId: policy.id.id as string,
 63→      policyVersion: policy.version,
 64→      humanVetoRequired: policy.human_veto_required,
 65→      rule,
 66→    })),
 67→  );
 68→
 69→  return annotated.sort((a, b) => b.rule.priority - a.rule.priority);
 70→};
 71→
 72→export const evaluateRulesAgainstContext = (
 73→  rules: AnnotatedRule[],
 74→  context: IntentEvaluationContext,
 75→): EvaluationResult => {
 76→  const contextRecord = context as unknown as Record<string, unknown>;
 77→  const evaluatedRules: EvaluatedRule[] = [];
 78→  const allWarnings: PolicyGateWarning[] = [];
 79→
 80→  for (const annotated of rules) {
 81→    const { matched, warnings } = evaluateCondition(
 82→      contextRecord,
 83→      annotated.rule.condition,
 84→      annotated.rule.id,
 85→      annotated.policyId,
 86→    );
 87→
 88→    allWarnings.push(...warnings);
 89→    evaluatedRules.push({ ...annotated, matched, warnings });
 90→
 91→    if (matched && annotated.rule.effect === "deny") {
 92→      return {
 93→        evaluatedRules,
 94→        denyMatched: true,
 95→        warnings: allWarnings,
 96→      };
 97→    }
 98→  }
 99→
100→  return {
101→    evaluatedRules,
102→    denyMatched: false,
103→    warnings: allWarnings,
104→  };
105→};
106→
107→/**
108→ * Extracts evidence requirements from matched evidence_requirement rules.
109→ * Returns the first (highest-priority) matched requirement, since rules
110→ * are already sorted by priority DESC.
111→ */
112→export const extractEvidenceRequirements = (
113→  evaluatedRules: EvaluatedRule[],
114→): PolicyEvidenceRequirements | undefined => {
115→  const matchedRequirement = evaluatedRules.find(
116→    (entry) =>
117→      entry.matched && entry.rule.effect === "evidence_requirement",
118→  );
119→
120→  if (!matchedRequirement) return undefined;
121→
122→  return {
123→    min_count: matchedRequirement.rule.min_evidence_count ?? 1,
124→    ...(matchedRequirement.rule.required_types
125→      ? { required_types: matchedRequirement.rule.required_types }
126→      : {}),
127→  };
128→};
129→
130→export const buildGateResult = (
131→  evaluatedRules: EvaluatedRule[],
132→  denyMatched: boolean,
133→  warnings: PolicyGateWarning[],
134→  evidenceRequirements?: PolicyEvidenceRequirements,
135→): PolicyGateResult => {
136→  const policyTrace: PolicyTraceEntry[] = evaluatedRules.map((entry) => ({
137→    policy_id: entry.policyId,
138→    policy_version: entry.policyVersion,
139→    rule_id: entry.rule.id,
140→    effect: entry.rule.effect,
141→    matched: entry.matched,
142→    priority: entry.rule.priority,
143→  }));
144→
145→  if (denyMatched) {
146→    const denyRule = evaluatedRules.find(
147→      (entry) => entry.matched && entry.rule.effect === "deny",
148→    );
149→    return {
150→      passed: false,
151→      reason: `Policy deny rule '${denyRule!.rule.id}' matched`,
152→      policy_trace: policyTrace,
153→      deny_rule_id: denyRule!.rule.id,
154→      warnings,
155→    };
156→  }
157→
158→  const humanVetoRequired = evaluatedRules.some(
159→    (entry) => entry.humanVetoRequired,
160→  );
161→
162→  return {
163→    passed: true,
164→    policy_trace: policyTrace,
165→    human_veto_required: humanVetoRequired,
166→    warnings,
167→    ...(evidenceRequirements ? { evidence_requirements: evidenceRequirements } : {}),
168→  };
169→};
170→
171→// ---------------------------------------------------------------------------
172→// Composition Root (single effect boundary)
173→// ---------------------------------------------------------------------------
174→
175→export const evaluatePolicyGate = async (
176→  surreal: Surreal,
177→  identityId: RecordId<"identity">,
178→  workspaceId: RecordId<"workspace">,
179→  intentContext: IntentEvaluationContext,
180→): Promise<PolicyGateResult> => {
181→  // Effect boundary: single DB read
182→  const rawPolicies = await loadActivePolicies(surreal, identityId, workspaceId);
183→
184→  // Pure pipeline
185→  const deduplicated = deduplicatePolicies(rawPolicies);
186→  const sortedRules = collectAndSortRules(deduplicated);
187→  const { evaluatedRules, denyMatched, warnings } = evaluateRulesAgainstContext(
188→    sortedRules,
189→    intentContext,
190→  );
191→  const evidenceRequirements = extractEvidenceRequirements(evaluatedRules);
192→
193→  return buildGateResult(evaluatedRules, denyMatched, warnings, evidenceRequirements);
194→};
195→

  1→import type {
  2→  RulePredicate,
  3→  RuleCondition,
  4→  PolicyGateWarning,
  5→} from "./types";
  6→
  7→// ---------------------------------------------------------------------------
  8→// Dot-Path Resolution
  9→// ---------------------------------------------------------------------------
 10→
 11→export const resolveDotPath = (
 12→  context: Record<string, unknown>,
 13→  path: string,
 14→): unknown | undefined => {
 15→  const segments = path.split(".");
 16→  let current: unknown = context;
 17→
 18→  for (const segment of segments) {
 19→    if (current === null) {
 20→      throw new Error(`Contract violation: null encountered in context at segment '${segment}'`);
 21→    }
 22→    if (current === undefined || typeof current !== "object") {
 23→      return undefined;
 24→    }
 25→    current = (current as Record<string, unknown>)[segment];
 26→  }
 27→
 28→  return current;
 29→};
 30→
 31→// ---------------------------------------------------------------------------
 32→// Predicate Evaluation (single predicate -> boolean)
 33→// ---------------------------------------------------------------------------
 34→
 35→const applyOperator = (
 36→  resolved: unknown,
 37→  operator: RulePredicate["operator"],
 38→  value: RulePredicate["value"],
 39→): boolean => {
 40→  switch (operator) {
 41→    case "eq":
 42→      return resolved === value;
 43→    case "neq":
 44→      return resolved !== value;
 45→    case "lt":
 46→      return typeof resolved === "number" && typeof value === "number" && resolved < value;
 47→    case "lte":
 48→      return typeof resolved === "number" && typeof value === "number" && resolved <= value;
 49→    case "gt":
 50→      return typeof resolved === "number" && typeof value === "number" && resolved > value;
 51→    case "gte":
 52→      return typeof resolved === "number" && typeof value === "number" && resolved >= value;
 53→    case "in":
 54→      return Array.isArray(value) && value.includes(resolved as string);
 55→    case "not_in":
 56→      return Array.isArray(value) && !value.includes(resolved as string);
 57→    case "exists":
 58→      return resolved !== undefined;
 59→  }
 60→};
 61→
 62→export const evaluatePredicate = (
 63→  context: Record<string, unknown>,
 64→  predicate: RulePredicate,
 65→): boolean => {
 66→  const resolved = resolveDotPath(context, predicate.field);
 67→
 68→  if (resolved === undefined && predicate.operator !== "exists") {
 69→    return false;
 70→  }
 71→
 72→  return applyOperator(resolved, predicate.operator, predicate.value);
 73→};
 74→
 75→// ---------------------------------------------------------------------------
 76→// Condition Evaluation (single or AND-array -> matched + warnings)
 77→// ---------------------------------------------------------------------------
 78→
 79→const isPredicateArray = (condition: RuleCondition): condition is RulePredicate[] =>
 80→  Array.isArray(condition);
 81→
 82→const fieldIsMissing = (
 83→  context: Record<string, unknown>,
 84→  field: string,
 85→): boolean => resolveDotPath(context, field) === undefined;
 86→
 87→const collectWarning = (
 88→  context: Record<string, unknown>,
 89→  predicate: RulePredicate,
 90→  ruleId: string,
 91→  policyId: string,
 92→): PolicyGateWarning | undefined =>
 93→  fieldIsMissing(context, predicate.field)
 94→    ? { rule_id: ruleId, field: predicate.field, policy_id: policyId }
 95→    : undefined;
 96→
 97→export const evaluateCondition = (
 98→  context: Record<string, unknown>,
 99→  condition: RuleCondition,
100→  ruleId: string,
101→  policyId: string,
102→): { matched: boolean; warnings: PolicyGateWarning[] } => {
103→  const predicates = isPredicateArray(condition) ? condition : [condition];
104→
105→  const warnings = predicates
106→    .map((predicate) => collectWarning(context, predicate, ruleId, policyId))
107→    .filter((warning): warning is PolicyGateWarning => warning !== undefined);
108→
109→  const matched = predicates.every((predicate) =>
110→    evaluatePredicate(context, predicate),
111→  );
112→
113→  return { matched, warnings };
114→};
115→

  1→import type { RecordId } from "surrealdb";
  2→
  3→// ---------------------------------------------------------------------------
  4→// Rule Predicates & Conditions
  5→// ---------------------------------------------------------------------------
  6→
  7→export type RulePredicate = {
  8→  field: string;
  9→  operator:
 10→    | "eq"
 11→    | "neq"
 12→    | "lt"
 13→    | "lte"
 14→    | "gt"
 15→    | "gte"
 16→    | "in"
 17→    | "not_in"
 18→    | "exists";
 19→  value: string | number | boolean | string[];
 20→};
 21→
 22→export type RuleCondition = RulePredicate | RulePredicate[];
 23→
 24→// ---------------------------------------------------------------------------
 25→// Policy Domain Types
 26→// ---------------------------------------------------------------------------
 27→
 28→export type PolicyRule = {
 29→  id: string;
 30→  condition: RuleCondition;
 31→  effect: "allow" | "deny" | "evidence_requirement";
 32→  priority: number;
 33→  /** Minimum evidence count required (only for evidence_requirement rules) */
 34→  min_evidence_count?: number;
 35→  /** Required evidence entity types (only for evidence_requirement rules) */
 36→  required_types?: string[];
 37→};
 38→
 39→export type PolicySelector = {
 40→  workspace?: string;
 41→  agent_role?: string;
 42→  resource?: string;
 43→};
 44→
 45→export type PolicyStatus =
 46→  | "draft"
 47→  | "testing"
 48→  | "active"
 49→  | "deprecated"
 50→  | "superseded";
 51→
 52→export type PolicyRecord = {
 53→  id: RecordId<"policy">;
 54→  title: string;
 55→  description?: string;
 56→  version: number;
 57→  status: PolicyStatus;
 58→  selector: PolicySelector;
 59→  rules: PolicyRule[];
 60→  human_veto_required: boolean;
 61→  max_ttl?: string;
 62→  created_by: RecordId<"identity">;
 63→  workspace: RecordId<"workspace">;
 64→  supersedes?: RecordId<"policy">;
 65→  created_at: Date;
 66→  updated_at?: Date;
 67→};
 68→
 69→// ---------------------------------------------------------------------------
 70→// Policy Trace (recorded on intent.evaluation)
 71→// ---------------------------------------------------------------------------
 72→
 73→export type PolicyTraceEntry = {
 74→  policy_id: string;
 75→  policy_version: number;
 76→  rule_id: string;
 77→  effect: "allow" | "deny" | "evidence_requirement";
 78→  matched: boolean;
 79→  priority: number;
 80→};
 81→
 82→// ---------------------------------------------------------------------------
 83→// Policy Gate Result (output of policy evaluation pipeline)
 84→// ---------------------------------------------------------------------------
 85→
 86→export type PolicyGateWarning = {
 87→  rule_id: string;
 88→  field: string;
 89→  policy_id: string;
 90→};
 91→
 92→export type PolicyEvidenceRequirements = {
 93→  min_count: number;
 94→  required_types?: string[];
 95→};
 96→
 97→export type PolicyGateResult =
 98→  | {
 99→      passed: true;
100→      policy_trace: PolicyTraceEntry[];
101→      human_veto_required: boolean;
102→      warnings: PolicyGateWarning[];
103→      evidence_requirements?: PolicyEvidenceRequirements;
104→    }
105→  | {
106→      passed: false;
107→      reason: string;
108→      policy_trace: PolicyTraceEntry[];
109→      deny_rule_id: string;
110→      warnings: PolicyGateWarning[];
111→    };
112→
113→// ---------------------------------------------------------------------------
114→// Intent Evaluation Context (input to policy gate)
115→// ---------------------------------------------------------------------------
116→
117→export type IntentEvaluationContext = {
118→  goal: string;
119→  reasoning: string;
120→  priority: number;
121→  action_spec: {
122→    provider: string;
123→    action: string;
124→    params?: Record<string, unknown>;
125→  };
126→  budget_limit?: { amount: number; currency: string };
127→  authorization_details?: Array<{
128→    type: string;
129→    action: string;
130→    resource: string;
131→    constraints?: Record<string, unknown>;
132→  }>;
133→  requester_type: string;
134→  requester_role?: string;
135→  /** Behavior scores keyed by metric_type (e.g. Security_First, TDD_Adherence).
136→   *  Populated by enrichBehaviorScores before policy gate evaluation.
137→   *  Empty object when no behavior data exists for the agent. */
138→  behavior_scores?: Record<string, number>;
139→};
