104→  ) => Promise<void>;
105→  /** Optional: evidence references (RecordIds) attached to the intent */
106→  evidenceRefs?: ReadonlyArray<RecordId>;
107→  /** Optional: workspace evidence enforcement mode */
108→  evidenceEnforcementMode?: EvidenceEnforcementMode;
109→  /** Optional: intent created_at for temporal ordering check */
110→  intentCreatedAt?: Date;
111→  /** Optional: requester agent name for authorship independence check */
112→  requesterAgent?: string;
113→  /** Optional: minimum evidence age in minutes (from workspace settings) */
114→  minEvidenceAgeMinutes?: number;
