  1→/**
  2→ * Inline rule editor for policy creation.
  3→ *
  4→ * Each rule has a condition (field/operator/value), effect (allow/deny), and priority.
  5→ * Pure state transformations are extracted as standalone functions.
  6→ * Field autocomplete is sourced from IntentEvaluationContext shape.
  7→ */
  8→
  9→import { useState, useRef, useEffect, useCallback } from "react";
 10→import { Button } from "../ui/button";
 11→
 12→// ---------------------------------------------------------------------------
 13→// Known fields from IntentEvaluationContext
 14→// ---------------------------------------------------------------------------
 15→
 16→export type FieldType = "string" | "number";
 17→
 18→export type FieldSuggestion = {
 19→  path: string;
 20→  type: FieldType;
 21→  description: string;
 22→};
 23→
 24→export const KNOWN_FIELDS: FieldSuggestion[] = [
 25→  { path: "goal", type: "string", description: "Intent goal statement" },
 26→  { path: "reasoning", type: "string", description: "Intent reasoning" },
 27→  { path: "priority", type: "number", description: "Intent priority level" },
 28→  { path: "action_spec.action", type: "string", description: "Action to perform" },
 29→  { path: "action_spec.provider", type: "string", description: "Service provider" },
 30→  { path: "action_spec.tool", type: "string", description: "Tool identifier" },
 31→  { path: "budget_limit.amount", type: "number", description: "Budget amount limit" },
 32→  { path: "budget_limit.currency", type: "string", description: "Budget currency code" },
 33→  { path: "authorization_details.type", type: "string", description: "Authorization type" },
 34→  { path: "requester_type", type: "string", description: "Type of requester" },
 35→  { path: "requester_role", type: "string", description: "Role of requester" },
 36→];
 37→
 38→// ---------------------------------------------------------------------------
 39→// Pure functions: autocomplete filtering
 40→// ---------------------------------------------------------------------------
 41→
 42→export function filterFields(query: string, knownFields: FieldSuggestion[]): FieldSuggestion[] {
 43→  if (query.length === 0) return knownFields;
 44→  const lower = query.toLowerCase();
 45→  return knownFields.filter((f) => f.path.toLowerCase().includes(lower));
 46→}
 47→
 48→export function lookupFieldType(fieldPath: string, knownFields: FieldSuggestion[]): FieldType | undefined {
 49→  return knownFields.find((f) => f.path === fieldPath)?.type;
 50→}
 51→
 52→// ---------------------------------------------------------------------------
 53→// Pure functions: operator filtering by field type
 54→// ---------------------------------------------------------------------------
 55→
 56→const OPERATORS = [
 57→  { value: "eq", label: "equals" },
 58→  { value: "neq", label: "not equals" },
 59→  { value: "gt", label: "greater than" },
 60→  { value: "gte", label: "greater or equal" },
 61→  { value: "lt", label: "less than" },
 62→  { value: "lte", label: "less or equal" },
 63→  { value: "in", label: "in" },
 64→  { value: "not_in", label: "not in" },
 65→  { value: "exists", label: "exists" },
 66→] as const;
 67→
 68→const STRING_OPERATORS: ReadonlySet<string> = new Set(["eq", "neq", "in", "not_in", "exists"]);
 69→const NUMBER_OPERATORS: ReadonlySet<string> = new Set(["eq", "neq", "gt", "gte", "lt", "lte", "exists"]);
 70→
 71→export function getOperatorsForType(fieldType?: FieldType) {
 72→  if (fieldType === "string") return OPERATORS.filter((op) => STRING_OPERATORS.has(op.value));
 73→  if (fieldType === "number") return OPERATORS.filter((op) => NUMBER_OPERATORS.has(op.value));
 74→  return [...OPERATORS];
 75→}
 76→
 77→// ---------------------------------------------------------------------------
 78→// Pure functions: human-readable rule preview
 79→// ---------------------------------------------------------------------------
 80→
 81→const OPERATOR_DISPLAY: Record<string, string> = {
 82→  eq: "equals", neq: "does not equal", gt: ">", gte: ">=", lt: "<", lte: "<=",
 83→  in: "is in", not_in: "is not in", exists: "exists",
 84→};
 85→
 86→export function formatRulePreview(field: string, operator: string, value: string, effect: string): string {
 87→  if (!field) return "";
 88→  const effectLabel = effect === "deny" ? "Deny" : "Allow";
 89→  const operatorLabel = OPERATOR_DISPLAY[operator] ?? operator;
 90→  if (operator === "exists") return `${effectLabel} when ${field} ${operatorLabel}`;
 91→  if (!value) return `${effectLabel} when ${field} ${operatorLabel} ...`;
 92→  return `${effectLabel} when ${field} ${operatorLabel} ${value}`;
 93→}
 94→
 95→const EFFECTS = [
 96→  { value: "allow", label: "Allow" },
 97→  { value: "deny", label: "Deny" },
 98→] as const;
 99→
100→export type RuleOperator = (typeof OPERATORS)[number]["value"];
101→export type RuleEffect = "allow" | "deny";
102→
103→export type RuleEntry = {
104→  id: string;
105→  field: string;
106→  operator: RuleOperator;
107→  value: string;
108→  effect: RuleEffect;
109→  priority: number;
110→};
111→
112→export function createEmptyRule(): RuleEntry {
113→  return { id: `rule-${crypto.randomUUID()}`, field: "", operator: "eq", value: "", effect: "allow", priority: 0 };
114→}
115→
116→export function updateRuleField<K extends keyof RuleEntry>(rules: RuleEntry[], ruleId: string, field: K, value: RuleEntry[K]): RuleEntry[] {
117→  return rules.map((rule) => rule.id === ruleId ? { ...rule, [field]: value } : rule);
118→}
119→
120→export function removeRule(rules: RuleEntry[], ruleId: string): RuleEntry[] {
121→  return rules.filter((rule) => rule.id !== ruleId);
122→}
123→
124→export function appendRule(rules: RuleEntry[]): RuleEntry[] {
125→  return [...rules, createEmptyRule()];
126→}
127→
128→export function ruleEntryToApiRule(entry: RuleEntry) {
129→  return { id: entry.id, condition: { field: entry.field, operator: entry.operator, value: entry.value }, effect: entry.effect, priority: entry.priority };
130→}
131→
132→// ---------------------------------------------------------------------------
133→// Components
134→// ---------------------------------------------------------------------------
135→
136→const inputClass = "h-7 rounded-md border border-input bg-background px-2 text-xs text-foreground focus:border-ring focus:outline-none";
137→const selectClass = "h-7 rounded-md border border-input bg-background px-1.5 text-xs text-foreground focus:border-ring focus:outline-none";
138→
139→type RuleBuilderProps = {
140→  rules: RuleEntry[];
141→  onRulesChange: (rules: RuleEntry[]) => void;
142→};
143→
144→function FieldAutocomplete({ value, onChange }: { value: string; onChange: (value: string) => void }) {
145→  const [showSuggestions, setShowSuggestions] = useState(false);
146→  const containerRef = useRef<HTMLDivElement>(null);
147→  const suggestions = filterFields(value, KNOWN_FIELDS);
148→
149→  const handleClickOutside = useCallback((e: MouseEvent) => {
150→    if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
151→      setShowSuggestions(false);
152→    }
153→  }, []);
154→
155→  useEffect(() => {
156→    document.addEventListener("mousedown", handleClickOutside);
157→    return () => document.removeEventListener("mousedown", handleClickOutside);
158→  }, [handleClickOutside]);
159→
160→  return (
161→    <div className="relative" ref={containerRef}>
162→      <input
163→        type="text"
164→        className={`${inputClass} w-full`}
165→        placeholder="Field (e.g. goal)"
166→        value={value}
167→        onChange={(e) => { onChange(e.target.value); setShowSuggestions(true); }}
168→        onFocus={() => setShowSuggestions(true)}
169→      />
170→      {showSuggestions && suggestions.length > 0 && (
171→        <ul className="absolute top-full z-10 mt-1 max-h-48 w-64 overflow-y-auto rounded-md border border-border bg-popover shadow-lg">
172→          {suggestions.map((s) => (
173→            <li key={s.path}>
174→              <button
175→                type="button"
176→                className="flex w-full flex-col gap-0.5 px-2 py-1.5 text-left text-xs transition-colors hover:bg-hover"
177→                onMouseDown={(e) => e.preventDefault()}
178→                onClick={() => { onChange(s.path); setShowSuggestions(false); }}
179→              >
180→                <span className="flex items-center gap-2">
181→                  <span className="font-mono text-foreground">{s.path}</span>
182→                  <span className="text-[0.6rem] text-muted-foreground">{s.type}</span>
183→                </span>
184→                <span className="text-muted-foreground">{s.description}</span>
185→              </button>
186→            </li>
187→          ))}
188→        </ul>
189→      )}
190→    </div>
191→  );
192→}
193→
194→function RuleRow({ rule, onUpdate, onRemove, canRemove }: {
195→  rule: RuleEntry;
196→  onUpdate: <K extends keyof RuleEntry>(field: K, value: RuleEntry[K]) => void;
197→  onRemove: () => void;
198→  canRemove: boolean;
199→}) {
200→  const fieldType = lookupFieldType(rule.field, KNOWN_FIELDS);
201→  const availableOperators = getOperatorsForType(fieldType);
202→  const preview = formatRulePreview(rule.field, rule.operator, rule.value, rule.effect);
203→
204→  return (
205→    <div className="flex flex-col gap-1">
206→      <div className="grid grid-cols-[1fr_120px_1fr_80px_60px_auto] gap-1.5">
207→        <FieldAutocomplete value={rule.field} onChange={(v) => onUpdate("field", v)} />
208→        <select className={selectClass} value={rule.operator} onChange={(e) => onUpdate("operator", e.target.value as RuleOperator)}>
209→          {availableOperators.map((op) => <option key={op.value} value={op.value}>{op.label}</option>)}
210→        </select>
211→        <input type={fieldType === "number" ? "number" : "text"} className={inputClass} placeholder="Value" value={rule.value} onChange={(e) => onUpdate("value", e.target.value)} />
212→        <select className={selectClass} value={rule.effect} onChange={(e) => onUpdate("effect", e.target.value as RuleEffect)}>
213→          {EFFECTS.map((eff) => <option key={eff.value} value={eff.value}>{eff.label}</option>)}
214→        </select>
215→        <input type="number" className={inputClass} placeholder="Pri" value={rule.priority} onChange={(e) => onUpdate("priority", Number.parseInt(e.target.value, 10) || 0)} />
216→        <Button variant="ghost" size="icon-xs" onClick={onRemove} disabled={!canRemove} title="Remove rule" className="text-destructive">
217→          &times;
218→        </Button>
219→      </div>
220→      {preview && <p className="text-[0.65rem] italic text-muted-foreground">{preview}</p>}
221→    </div>
222→  );
223→}
224→
225→export function RuleBuilder({ rules, onRulesChange }: RuleBuilderProps) {
226→  const handleUpdate = (ruleId: string) => {
227→    return <K extends keyof RuleEntry>(field: K, value: RuleEntry[K]) => {
228→      onRulesChange(updateRuleField(rules, ruleId, field, value));
229→    };
230→  };
231→
232→  const handleRemove = (ruleId: string) => () => { onRulesChange(removeRule(rules, ruleId)); };
233→  const handleAdd = () => { onRulesChange(appendRule(rules)); };
234→
235→  return (
236→    <div className="flex flex-col gap-2">
237→      <div className="flex items-center justify-between">
238→        <span className="text-sm font-medium text-foreground">Rules</span>
239→        <Button variant="outline" size="xs" onClick={handleAdd}>Add Rule</Button>
240→      </div>
241→
242→      {rules.length === 0 ? (
243→        <p className="py-4 text-center text-xs text-muted-foreground">No rules yet. Add at least one rule.</p>
244→      ) : (
245→        <div className="flex flex-col gap-2">
246→          <div className="grid grid-cols-[1fr_120px_1fr_80px_60px_auto] gap-1.5 text-[0.6rem] font-medium uppercase tracking-wider text-muted-foreground">
247→            <span>Field</span>
248→            <span>Operator</span>
249→            <span>Value</span>
250→            <span>Effect</span>
251→            <span>Pri</span>
252→            <span />
253→          </div>
254→          {rules.map((rule) => (
255→            <RuleRow key={rule.id} rule={rule} onUpdate={handleUpdate(rule.id)} onRemove={handleRemove(rule.id)} canRemove={rules.length > 1} />
256→          ))}
257→        </div>
258→      )}
259→    </div>
260→  );
261→}
