166→async function handlePolicyDetail(
167→  deps: ServerDependencies,
168→  workspaceId: string,
169→  policyId: string,
170→  request: Request,
171→): Promise<Response> {
172→  const identityOrError = await resolveIdentityFromSession(deps, request);
173→  if (isResponse(identityOrError)) return identityOrError;
174→
175→  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.detail.workspace_resolve.failed");
176→  if (isResponse(workspaceOrError)) return workspaceOrError;
177→  const workspaceRecord = workspaceOrError;
178→
179→  try {
180→    const policy = await getPolicyById(deps.surreal, policyId, workspaceRecord);
181→    if (!policy) {
182→      return jsonError("policy not found", 404);
183→    }
184→
185→    const edges = await getPolicyEdges(deps.surreal, policyId);
186→    const versionChain = await buildVersionChain(deps.surreal, policy);
187→
188→    return jsonResponse({
189→      policy: {
190→        id: policy.id.id as string,
191→        title: policy.title,
192→        description: policy.description,
193→        version: policy.version,
194→        status: policy.status,
195→        selector: policy.selector ?? {},
196→        rules: policy.rules ?? [],
197→        human_veto_required: policy.human_veto_required ?? false,
198→        ...(policy.max_ttl ? { max_ttl: policy.max_ttl } : {}),
199→        ...(policy.supersedes ? { supersedes: policy.supersedes.id as string } : {}),
200→        created_at: policy.created_at instanceof Date ? policy.created_at.toISOString() : String(policy.created_at),
201→        ...(policy.updated_at ? {
202→          updated_at: policy.updated_at instanceof Date ? policy.updated_at.toISOString() : String(policy.updated_at),
203→        } : {}),
204→      },
205→      edges,
206→      version_chain: versionChain,
207→    }, 200);
208→  } catch (error) {
209→    log.error("policy.detail.failed", "Failed to get policy detail", error, { workspaceId, policyId });
210→    return jsonError("failed to get policy detail", 500);
211→  }
212→}
