```typescript
async function handleCreatePolicy(
  deps: ServerDependencies,
  workspaceId: string,
  request: Request,
): Promise<Response> {
  const guardResult = await requireHumanIdentity(deps, request);
  if (isResponse(guardResult)) return guardResult;

  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.create.workspace_resolve.failed");
  if (isResponse(workspaceOrError)) return workspaceOrError;
  const workspaceRecord = workspaceOrError;

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return jsonError("invalid JSON body", 400);
  }

  const validation = validatePolicyCreateBody(body as { title: unknown; description: unknown; rules: unknown });
  if (!validation.valid) {
    return jsonError(validation.errors[0], 400);
  }

  const parsed = body as Record<string, unknown>;

  try {
    const { policyId } = await createPolicy(deps.surreal, {
      title: parsed.title as string,
      description: parsed.description as string,
      selector: parsed.selector as PolicySelector | undefined,
      rules: parsed.rules as PolicyRule[],
      human_veto_required: parsed.human_veto_required as boolean | undefined,
      max_ttl: parsed.max_ttl as string | undefined,
      createdBy: guardResult.identityRecord,
      workspace: workspaceRecord,
    });

    return jsonResponse({ policy_id: policyId }, 201);
  } catch (error) {
    log.error("policy.create.failed", "Failed to create policy", error, { workspaceId });
    return jsonError("failed to create policy", 500);
  }
}
```

**Activate handler (update to active):**
```typescript
async function handleActivatePolicy(
  deps: ServerDependencies,
  workspaceId: string,
  policyId: string,
  request: Request,
): Promise<Response> {
  const guardResult = await requireHumanIdentity(deps, request);
  if (isResponse(guardResult)) return guardResult;

  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.activate.workspace_resolve.failed");
  if (isResponse(workspaceOrError)) return workspaceOrError;
  const workspaceRecord = workspaceOrError;

  try {
    const policyRecord = new RecordId("policy", policyId);
    const policy = await deps.surreal.select<PolicyRecord>(policyRecord);

    if (!policy || (policy.workspace.id as string) !== (workspaceRecord.id as string)) {
      return jsonError("policy not found", 404);
    }

    if (!ACTIVATABLE_STATUSES.has(policy.status)) {
      return jsonError(
        `policy must be in draft or testing status to activate (current: ${policy.status})`,
        409,
      );
    }

    await activatePolicy(
      deps.surreal,
      policy,
      guardResult.identityRecord,
      workspaceRecord,
    );

    return jsonResponse({ status: "active" }, 200);
  } catch (error) {
    log.error("policy.activate.failed", "Failed to activate policy", error, { workspaceId, policyId });
    return jsonError("failed to activate policy", 500);
  }
}
```

---

## 4. `loadActivePolicies` query function

**File:** `/Users/marcus/conductor/workspaces/brain-v1/san-francisco-v2/app/src/server/policy/policy-queries.ts` (lines 63-96)

```typescript
export async function loadActivePolicies(
  surreal: Surreal,
  identityId: RecordId<"identity">,
  workspaceId: RecordId<"workspace">,
): Promise<PolicyRecord[]> {
  const identityResult = await surreal.query<
    [Array<{ policies: PolicyRecord[] }>]
  >(
    `SELECT ->governing->policy.* AS policies FROM $identity;`,
    { identity: identityId },
  );

  const workspaceResult = await surreal.query<
    [Array<{ policies: PolicyRecord[] }>]
  >(
    `SELECT <-protects<-policy.* AS policies FROM $workspace;`,
    { workspace: workspaceId },
  );

  const identityPolicies = identityResult[0]?.[0]?.policies ?? [];
  const workspacePolicies = workspaceResult[0]?.[0]?.policies ?? [];

  // Deduplicate by policy ID and filter active only
  const seen = new Set<string>();
  const result: PolicyRecord[] = [];
  for (const policy of [...identityPolicies, ...workspacePolicies]) {
    const id = policy.id.id as string;
    if (!seen.has(id) && policy.status === "active") {
      seen.add(id);
      result.push(policy);
    }
  }
  return result;
}
```

This function loads active policies from two relationships:
1. Policies governed directly by the identity (via `->governing->policy` edge)
2. Policies protecting the workspace (via `<-protects<-policy` edge)

It deduplicates and filters to only return policies with `status === "active"`.

