          "scenario_name": ""
        },
        {
          "id": "02-05",
          "name": "Version diff view for Rego source",
          "criteria": "VersionDiffView shows side-by-side or unified diff of rego_source between two policy versions. Uses CodeMirror merge addon or text diff component.",
          "test_file": "",
          "scenario_name": ""
        }
      ]
    },
    {
      "id": "03",
      "name": "Policy Test Endpoint + Panel",
      "steps": [
        {
          "id": "03-01",
          "name": "Backend: POST /policies/:id/test endpoint",
