          "id": "01-02",
          "name": "Schema migration: replace condition with rego_source",
          "criteria": "Migration 0088 removes rules[*].condition* fields from policy table, adds rego_source string field. bun migrate applies cleanly. INFO FOR TABLE policy shows rego_source field.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "01-03",
          "name": "RegoEvaluator: compile, evaluate, map to PolicyGateResult",
          "criteria": "compileRego() returns success or errors with line/column. evaluateRegoPolicy() queries data.osabio.policy.allow/deny/evidence_requirement, maps to RegoEvaluationResult. Package validation rejects non-osabio.policy packages. Engine cache stores compiled engines by policyId:version.",
          "test_file": "tests/unit/rego-evaluator.test.ts",
          "scenario_name": "evaluateRegoPolicy returns allow, deny with messages, evidence requirement, and fail-closed on no match"
        },
        {
          "id": "01-04",
          "name": "Wire RegoEvaluator into policy gate, remove predicate evaluator",
          "criteria": "evaluatePolicyGate() calls evaluateRegoPolicy() for each policy. predicate-evaluator.ts deleted. PolicyRecord type uses rego_source instead of rules. Existing evaluatePolicyGate() signature unchanged. Walking skeleton acceptance test passes: create Rego policy, activate, evaluate intent, verify deny/allow and policy trace.",
          "test_file": "tests/acceptance/policy-node/walking-skeleton.test.ts",
          "scenario_name": "active deny policy blocks a deploy intent and records policy trace"
        },
        {
          "id": "01-05",
          "name": "Rego compilation validation on policy create/update",
          "criteria": "POST /policies with invalid Rego returns 400 with {line, column, message}. POST /policies with wrong package returns 400. POST /policies with valid Rego creates draft policy. POST /policies with legacy rules field returns 400. policy-validation.ts rewritten for Rego compilation.",
          "test_file": "tests/unit/policy-validation.test.ts",
          "scenario_name": "rejects invalid Rego syntax with line/column errors"
        },
        {
          "id": "01-06",
          "name": "Update acceptance tests for Rego policy lifecycle",
          "criteria": "All tests in policy-node/ pass with rego_source payloads. policy-test-kit.ts types updated (PolicyRecord, CreatePolicyOptions use rego_source). Milestone-1 tests create/activate/deprecate/version Rego policies. Milestone-2 tests evaluate Rego policies via policy gate with deny short-circuit, allow, fail-closed, evidence requirement, and human veto scenarios.",
          "test_file": "tests/acceptance/policy-node/milestone-2-policy-gate-evaluation.test.ts",
          "scenario_name": "deny rule at priority 100 blocks intent before lower-priority allow rule is evaluated"
        }
      ]
    },
    {
      "id": "02",
      "name": "UI — Rego Editor + Validation",
      "steps": [
        {
          "id": "02-01",
          "name": "Add CodeMirror 5 with codemirror-rego dependency",
          "criteria": "codemirror, codemirror-rego, and react-codemirror2 installed. A minimal RegoEditor component renders with mode: 'rego', line numbers, and bracket matching.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "02-02",
          "name": "Replace RuleBuilder with RegoEditor in CreatePolicyDialog",
          "criteria": "CreatePolicyDialog renders RegoEditor instead of RuleBuilder. Form submits rego_source string to POST /policies. Field reference panel shows IntentEvaluationContext fields. RuleBuilder.tsx deleted.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "02-03",
          "name": "Add Validate button with inline error display",
          "criteria": "Validate button calls POST /policies/validate. On success, green checkmark shown. On failure, Regorus compilation errors displayed inline with line numbers. CodeMirror gutter markers highlight error lines.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "02-04",
          "name": "Display rego_source on policy detail page",
          "criteria": "PolicyDetailPage renders rego_source in read-only CodeMirror with mode: 'rego' and readOnly: true. Syntax highlighted. No edit capability in detail view.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "02-05",
          "name": "Version diff view for Rego source",
          "criteria": "VersionDiffView shows side-by-side or unified diff of rego_source between two policy versions. Uses CodeMirror merge addon or text diff component.",
          "test_file": "",
          "scenario_name": ""
        }
      ]
    },
    {
      "id": "03",
      "name": "Policy Test Endpoint + Panel",
      "steps": [
        {
          "id": "03-01",
          "name": "Backend: POST /policies/:id/test endpoint",
          "criteria": "Endpoint accepts mock IntentEvaluationContext JSON, evaluates policy rego_source via RegoEvaluator, returns { decision: allow|deny, messages: string[], evidence_requirement?: object }. Returns 404 for non-existent policy. Returns 400 for invalid input.",
          "test_file": "tests/acceptance/policy-node/milestone-3-rego-test-endpoint.test.ts",
          "scenario_name": "test policy with mock input that triggers deny"
        },
        {
          "id": "03-02",
          "name": "Backend: POST /policies/validate endpoint",
          "criteria": "Endpoint accepts { rego_source: string }, compiles via Regorus, returns { success: true } or { success: false, errors: CompileError[] }. No policy record created. Used by UI Validate button.",
          "test_file": "tests/acceptance/policy-node/milestone-3-rego-test-endpoint.test.ts",
          "scenario_name": "validate endpoint returns compilation errors for invalid Rego"
        },
        {
          "id": "03-03",
          "name": "UI: PolicyTestPanel component",
          "criteria": "PolicyTestPanel renders on policy detail page. JSON editor (CodeMirror, mode: json) for mock IntentEvaluationContext input. Test button calls POST /policies/:id/test. Result displays decision (allow/deny) with messages. Error states handled (400, 404, network).",
          "test_file": "",
          "scenario_name": ""
        }
      ]
    }
  ],
  "implementation_scope": {
    "source_directories": [
      "app/src/server/policy/",
      "app/src/client/components/policy/",
      "vendor/regorus-wasm/",
      "schema/migrations/"
    ],
    "test_directories": [
      "tests/unit/",
      "tests/acceptance/policy-node/"
    ],
    "excluded_patterns": [
      "node_modules/**",
      "vendor/regorus-src/**"
    ]
  },
  "validation": {
    "status": "pending",
    "reviewer": "nw-solution-architect-reviewer",
